//! The `chatgpt` provider end to end (#474, PR 4): the agent on a ChatGPT
//! plan, against a fake OpenAI (`wiremock`) that plays the sign-in endpoints
//! and the API on one address. No real credentials: the ID tokens are signed
//! with a key generated by the test, and the provider is pointed at the mock
//! through the `test-endpoints` seam that no build of the app has.
//!
//! What this pins, in the order of the PR 4 gates on #474:
//!
//! * the request the route takes: `store: false`, `stream: true`,
//!   `instructions`, one `edytlab` namespace, nothing the preview refuses;
//! * a fresh bearer for each request, and exactly one renewal and resend on a
//!   `401`;
//! * the usage limit (and every other code on the errors page) as its own
//!   error with no second request and no fallback to another provider;
//! * reasoning items asked for, echoed within a turn, never across turns;
//! * the tool list is a choice (full or slim) that stays in the namespace;
//! * the classifier is not called;
//! * the model list and the TEST probe;
//! * the bearer goes only where the provider sends it.

mod chatgpt_support;
mod common;
mod oauth_support;

use std::sync::{Arc, Mutex};

use ai::chatgpt::session::{ChatGptSession, SessionState};
use ai::chatgpt::{PlanUsageError, PlanUsageKind};
use ai::responses::UNSUPPORTED_FIELDS;
use ai::{Agent, AgentEvent, ChatGptProvider, Error, LlmConfig, ToolSet};
use chatgpt_support::{Fake, MemoryStore};
use common::{ok, Entry, SeqResponder};
use serde_json::{json, Value};
use tools::schema::{anthropic_tool, object_schema};
use tools::{Tool, ToolContext, ToolDispatcher, ToolResult};
use wiremock::matchers::{method, path};
use wiremock::{Mock, ResponseTemplate};

// ---------------------------------------------------------------------
// The rig
// ---------------------------------------------------------------------

/// A fake OpenAI with a signed-in session, and where the files go.
struct Rig {
    fake: Arc<Fake>,
    session: Arc<ChatGptSession>,
    dir: tempfile::TempDir,
    /// The plan gate every agent of the rig is built with.
    gate: ai::PlanGate,
}

impl Rig {
    async fn new() -> Self {
        let fake = Fake::start().await;
        let dir = tempfile::tempdir().unwrap();
        let session = fake.signed_in(dir.path(), MemoryStore::new()).await;
        Self {
            fake,
            session: Arc::new(session),
            dir,
            gate: ai::PlanGate::new(),
        }
    }

    /// `/v1/responses` answers `script` in order.
    async fn answers(&self, script: Vec<Entry>) {
        Mock::given(method("POST"))
            .and(path("/v1/responses"))
            .respond_with(SeqResponder::new(script))
            .mount(&self.fake.server)
            .await;
    }

    fn provider(&self) -> ChatGptProvider {
        ChatGptProvider::loopback_for_tests(&self.fake.issuer()).expect("a loopback address")
    }

    fn config(&self) -> LlmConfig {
        LlmConfig::new_chatgpt_with(self.provider(), self.session.clone())
    }

    fn agent_with(&self, cfg: LlmConfig, dispatcher: ToolDispatcher) -> Agent {
        let store = session::Store::open(self.dir.path()).expect("open store");
        Agent::new(
            cfg,
            Arc::new(Mutex::new(dispatcher)),
            Arc::new(Mutex::new(store)),
            Arc::new(Mutex::new(audio_engine::Engine::new())),
            self.gate.clone(),
            Arc::new(Mutex::new(None::<tools::Clipboard>)),
        )
    }

    fn agent(&self) -> Agent {
        self.agent_with(self.config(), echo_dispatcher())
    }

    /// Every request the API received on `route`, in order.
    async fn received(&self, route: &str) -> Vec<wiremock::Request> {
        self.fake
            .server
            .received_requests()
            .await
            .expect("recording is on")
            .into_iter()
            .filter(|r| r.url.path() == route)
            .collect()
    }

    async fn bodies(&self) -> Vec<Value> {
        self.received("/v1/responses")
            .await
            .iter()
            .map(|r| serde_json::from_slice(&r.body).expect("a JSON body"))
            .collect()
    }

    async fn bearers(&self) -> Vec<String> {
        self.received("/v1/responses")
            .await
            .iter()
            .map(|r| {
                r.headers
                    .get("authorization")
                    .map(|v| v.to_str().unwrap().to_string())
                    .unwrap_or_default()
            })
            .collect()
    }
}

/// A tool the model can call, so a turn has a tool round trip.
struct Echo;

impl Tool for Echo {
    fn name(&self) -> &'static str {
        "echo"
    }
    fn schema(&self) -> Value {
        anthropic_tool(
            "echo",
            "Reads the session.",
            object_schema(&[("track", "integer", true)]),
        )
    }
    fn mutates(&self) -> bool {
        false
    }
    fn invoke(&self, _args: Value, _ctx: &mut ToolContext) -> tools::Result<ToolResult> {
        Ok(ToolResult::Ok(json!({ "ok": true })))
    }
}

fn echo_dispatcher() -> ToolDispatcher {
    let mut dispatcher = ToolDispatcher::new();
    dispatcher.register(Box::new(Echo));
    dispatcher
}

// --- Responses API streams ---------------------------------------------------------

fn frames(events: &[Value]) -> String {
    events
        .iter()
        .map(|e| format!("event: {}\ndata: {e}\n\n", e["type"].as_str().unwrap()))
        .collect()
}

fn completed() -> Value {
    json!({ "type": "response.completed", "response": { "id": "resp_1", "status": "completed" } })
}

fn text_stream(text: &str) -> String {
    frames(&[
        json!({ "type": "response.created", "response": { "id": "resp_1" } }),
        json!({
            "type": "response.output_item.added", "output_index": 0,
            "item": { "type": "message", "id": "msg_1", "role": "assistant", "content": [] }
        }),
        json!({
            "type": "response.output_text.delta",
            "item_id": "msg_1", "output_index": 0, "content_index": 0, "delta": text
        }),
        completed(),
    ])
}

/// A step that reasons (when `reasoning` is the item's encrypted content) and
/// then calls `echo`.
fn tool_stream(reasoning: Option<&str>, call_id: &str) -> String {
    let mut events = vec![json!({ "type": "response.created", "response": { "id": "resp_1" } })];
    let mut at = 0;
    if let Some(encrypted) = reasoning {
        events.push(json!({
            "type": "response.output_item.done", "output_index": at,
            "item": {
                "type": "reasoning", "id": "rs_secret_id", "summary": [],
                "encrypted_content": encrypted
            }
        }));
        at += 1;
    }
    events.push(json!({
        "type": "response.output_item.added", "output_index": at,
        "item": { "type": "function_call", "id": "fc_1", "call_id": call_id, "name": "echo", "arguments": "" }
    }));
    events.push(json!({
        "type": "response.function_call_arguments.delta",
        "item_id": "fc_1", "output_index": at, "delta": "{\"track\":1}"
    }));
    events.push(json!({
        "type": "response.function_call_arguments.done",
        "item_id": "fc_1", "output_index": at, "arguments": "{\"track\":1}"
    }));
    events.push(completed());
    frames(&events)
}

fn failed_stream(code: &str, message: &str) -> String {
    frames(&[
        json!({ "type": "response.created", "response": { "id": "resp_1" } }),
        json!({
            "type": "response.failed",
            "response": { "id": "resp_1", "error": { "code": code, "message": message } }
        }),
    ])
}

fn error_body(code: &str, param: Option<&str>) -> String {
    json!({ "error": { "code": code, "message": "OpenAI's words", "param": param } }).to_string()
}

async fn turn(agent: &mut Agent, message: &str) -> (ai::Result<ai::TurnResult>, Vec<AgentEvent>) {
    let mut events = Vec::new();
    let result = agent
        .turn(message.to_string(), |event| events.push(event))
        .await;
    (result, events)
}

fn plan_usage(result: ai::Result<ai::TurnResult>) -> PlanUsageError {
    match result {
        Err(Error::PlanUsage(error)) => error,
        other => panic!("wanted a plan usage error, got {other:?}"),
    }
}

// ---------------------------------------------------------------------
// The request
// ---------------------------------------------------------------------

#[tokio::test]
async fn a_turn_sends_what_the_route_takes_and_nothing_it_refuses() {
    let rig = Rig::new().await;
    rig.answers(vec![ok(text_stream("Hello."))]).await;
    let mut agent = rig.agent();

    let (result, events) = turn(&mut agent, "hi").await;

    let result = result.expect("the turn succeeds");
    assert_eq!(result.text, "Hello.");
    assert!(events
        .iter()
        .any(|e| matches!(e, AgentEvent::TextDelta(t) if t == "Hello.")));

    // One request in all: the mode classifier is not called, and there is no
    // second provider to ask.
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 1, "{bodies:?}");
    assert!(
        !bodies[0]
            .to_string()
            .contains("Classify the user's request"),
        "the classifier ran"
    );
    let body = &bodies[0];
    assert_eq!(body["store"], json!(false));
    assert_eq!(body["stream"], json!(true));
    assert!(
        body["instructions"].as_str().is_some_and(|i| !i.is_empty()),
        "{body}"
    );
    assert_eq!(body["input"][0]["type"], "message");
    assert_eq!(body["input"][0]["role"], "user");
    assert_eq!(body["input"][0]["content"][0]["type"], "input_text");
    assert_eq!(body["input"][0]["content"][0]["text"], "hi");
    assert_eq!(body["tool_choice"], "auto");
    assert_eq!(body["include"], json!(["reasoning.encrypted_content"]));

    // No system item (refused), no chat-shaped fields, none of the fields the
    // preview lists.
    let object = body.as_object().unwrap();
    for field in UNSUPPORTED_FIELDS {
        assert!(!object.contains_key(*field), "{field}: {body}");
    }
    for field in [
        "system",
        "messages",
        "max_tokens",
        "max_completion_tokens",
        "reasoning_effort",
        "output_config",
        "thinking",
    ] {
        assert!(!object.contains_key(field), "{field}: {body}");
    }
    assert!(
        body["input"]
            .as_array()
            .unwrap()
            .iter()
            .all(|item| item["role"] != "system"),
        "{body}"
    );

    // The tools are one namespace, not a flat list.
    let tools = body["tools"].as_array().unwrap();
    assert_eq!(tools.len(), 1, "{tools:?}");
    assert_eq!(tools[0]["type"], "namespace");
    assert_eq!(tools[0]["name"], "edytlab");
    assert_eq!(tools[0]["tools"][0]["type"], "function");
    assert_eq!(tools[0]["tools"][0]["name"], "echo");
    assert_eq!(tools[0]["tools"][0]["strict"], json!(false));

    // And the bearer is the session's, nothing else.
    assert_eq!(rig.bearers().await, ["Bearer AT-1"]);
    assert!(rig.received("/v1/responses").await[0]
        .headers
        .get("x-api-key")
        .is_none());
}

/// The classifier is the second request of every turn on the other providers.
/// Here it is the one that would spend the person's allowance for a word, so
/// it is not made; every message is general, and Plan first is unaffected.
#[tokio::test]
async fn the_mode_classifier_is_never_called() {
    let rig = Rig::new().await;
    rig.answers(vec![ok(text_stream("one")), ok(text_stream("two"))])
        .await;
    let mut agent = rig.agent();

    // A request every other provider would classify as a mashup (and hold for
    // a plan).
    let (first, events) = turn(&mut agent, "mash these two songs up").await;
    first.expect("the turn succeeds");
    assert!(
        !events.iter().any(|e| matches!(e, AgentEvent::Plan { .. })),
        "a mashup is no longer held for a plan without Plan first"
    );
    let (second, _) = turn(&mut agent, "and again").await;
    second.expect("the turn succeeds");

    assert_eq!(
        rig.bodies().await.len(),
        2,
        "one request per turn: no classifier call"
    );
}

#[tokio::test]
async fn the_full_tool_list_and_the_slim_one_both_stay_in_the_namespace() {
    let rig = Rig::new().await;
    rig.answers(vec![ok(text_stream("a")), ok(text_stream("b"))])
        .await;
    let count = ToolDispatcher::default_dispatcher().tool_names().len();
    assert!(
        count > 60,
        "the real registry is what is being sized: {count}"
    );

    for (set, label) in [(ToolSet::Full, "full"), (ToolSet::Slim, "slim")] {
        let provider = rig.provider().with_tool_set(set);
        let cfg = LlmConfig::new_chatgpt_with(provider, rig.session.clone());
        let mut agent = rig.agent_with(cfg, ToolDispatcher::default_dispatcher());
        let (result, _) = turn(&mut agent, "Make track 0 louder by 6 dB.").await;
        result.unwrap_or_else(|e| panic!("{label}: {e}"));
    }

    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 2);
    let sizes: Vec<usize> = bodies
        .iter()
        .map(|body| {
            let tools = body["tools"].as_array().unwrap();
            assert_eq!(tools.len(), 1, "never a flat list: {tools:?}");
            assert_eq!(tools[0]["type"], "namespace");
            assert_eq!(tools[0]["name"], "edytlab");
            tools[0]["tools"].as_array().unwrap().len()
        })
        .collect();
    assert_eq!(sizes[0], count, "full: every tool, in one namespace");
    assert!(
        sizes[1] < sizes[0] / 2,
        "slim: a core and what the message names ({} of {count})",
        sizes[1]
    );
    // The slim request says which others exist, as on Ollama.
    assert!(bodies[1]["instructions"]
        .as_str()
        .unwrap()
        .contains("More tools you can call by exact name"));
    assert!(!bodies[0]["instructions"]
        .as_str()
        .unwrap()
        .contains("More tools you can call by exact name"));
}

// ---------------------------------------------------------------------
// Reasoning
// ---------------------------------------------------------------------

/// Within a turn the reasoning item goes back with the tool result that
/// follows it; the next turn starts without it (CLAUDE.md, the thinking rule:
/// the encrypted content is tied to the `system` and `tools` it was produced
/// under, and both are rebuilt every turn).
#[tokio::test]
async fn reasoning_is_echoed_within_a_turn_and_never_across_turns() {
    let rig = Rig::new().await;
    rig.answers(vec![
        ok(tool_stream(Some("ENC-1"), "call_1")),
        ok(text_stream("Track 1 is fine.")),
        ok(text_stream("Anything else?")),
    ])
    .await;
    let mut agent = rig.agent();

    let (first, _) = turn(&mut agent, "check track 1").await;
    first.expect("the first turn succeeds");
    let (second, _) = turn(&mut agent, "thanks").await;
    second.expect("the second turn succeeds");

    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 3);
    let kinds = |body: &Value| -> Vec<String> {
        body["input"]
            .as_array()
            .unwrap()
            .iter()
            .map(|item| match item["type"].as_str().unwrap() {
                "message" => format!("message:{}", item["role"].as_str().unwrap()),
                other => other.to_string(),
            })
            .collect()
    };

    // Step 2 of turn 1: user, the reasoning that led to the call, the call,
    // its output. In that order, and the reasoning without its id.
    assert_eq!(
        kinds(&bodies[1]),
        [
            "message:user",
            "reasoning",
            "function_call",
            "function_call_output"
        ]
    );
    let reasoning = &bodies[1]["input"][1];
    assert_eq!(reasoning["encrypted_content"], "ENC-1");
    assert!(reasoning.get("id").is_none(), "{reasoning}");
    assert_eq!(bodies[1]["input"][2]["call_id"], "call_1");
    assert_eq!(bodies[1]["input"][2]["namespace"], "edytlab");
    assert_eq!(bodies[1]["input"][3]["call_id"], "call_1");

    // Turn 2 keeps what was said and done, and none of the reasoning.
    let second_turn = kinds(&bodies[2]);
    assert!(
        !second_turn.iter().any(|k| k == "reasoning"),
        "reasoning crossed a turn: {second_turn:?}"
    );
    assert_eq!(
        second_turn,
        [
            "message:user",
            "function_call",
            "function_call_output",
            "message:assistant",
            "message:user"
        ]
    );
    assert!(!bodies[2].to_string().contains("ENC-1"));
    assert!(!bodies[2].to_string().contains("rs_secret_id"));
}

#[tokio::test]
async fn reasoning_can_be_turned_off_without_a_rewrite() {
    let rig = Rig::new().await;
    rig.answers(vec![
        ok(tool_stream(Some("ENC-1"), "call_1")),
        ok(text_stream("Done.")),
    ])
    .await;
    let provider = rig
        .provider()
        .with_reasoning(ai::chatgpt::ReasoningReplay::Off);
    let mut agent = rig.agent_with(
        LlmConfig::new_chatgpt_with(provider, rig.session.clone()),
        echo_dispatcher(),
    );

    let (result, _) = turn(&mut agent, "check track 1").await;
    result.expect("the turn succeeds");

    for body in rig.bodies().await {
        assert!(body.get("include").is_none(), "{body}");
        assert!(!body.to_string().contains("ENC-1"), "{body}");
    }
}

// ---------------------------------------------------------------------
// The bearer
// ---------------------------------------------------------------------

#[tokio::test]
async fn a_401_renews_once_and_sends_the_request_again() {
    let rig = Rig::new().await;
    rig.answers(vec![
        (401, error_body("invalid_token", None)),
        ok(text_stream("Hello.")),
    ])
    .await;
    let mut agent = rig.agent();

    let (result, _) = turn(&mut agent, "hi").await;

    assert_eq!(result.expect("the turn succeeds").text, "Hello.");
    assert_eq!(
        rig.fake.refresh_requests().len(),
        1,
        "one renewal for the one refusal"
    );
    assert_eq!(
        rig.bearers().await,
        ["Bearer AT-1", "Bearer AT-2"],
        "the second request carries the renewed token"
    );
}

#[tokio::test]
async fn a_second_401_is_a_session_that_ended_and_nothing_is_tried_a_third_time() {
    let rig = Rig::new().await;
    rig.answers(vec![
        (401, error_body("invalid_token", None)),
        (401, error_body("invalid_token", None)),
        ok(text_stream("never")),
    ])
    .await;
    let mut agent = rig.agent();

    let (result, _) = turn(&mut agent, "hi").await;

    let error = plan_usage(result);
    assert_eq!(error.code(), "session_ended", "{error}");
    assert_eq!(rig.received("/v1/responses").await.len(), 2);
    assert_eq!(rig.fake.refresh_requests().len(), 1, "renewed once");
}

#[tokio::test]
async fn a_refresh_the_issuer_refuses_ends_the_session_and_the_turn() {
    let rig = Rig::new().await;
    rig.answers(vec![(401, error_body("invalid_token", None))])
        .await;
    // devkit#5: the issuer refuses the refresh.
    rig.fake.knobs().refresh_error = Some((400, json!({ "error": "invalid_grant" })));
    let mut agent = rig.agent();

    let (result, _) = turn(&mut agent, "hi").await;

    assert_eq!(plan_usage(result).code(), "session_ended");
    assert_eq!(rig.received("/v1/responses").await.len(), 1);
    assert!(matches!(
        rig.session.status().state,
        SessionState::SessionEnded(_)
    ));
}

#[tokio::test]
async fn a_session_that_cannot_be_used_makes_no_request() {
    // Signed in, but the grant lacks `chatgpt.tokens.use.direct`.
    let fake = Fake::start().await;
    fake.knobs().scope = Some("email offline_access openid profile resource.invoke".into());
    let dir = tempfile::tempdir().unwrap();
    let session = Arc::new(fake.signed_in(dir.path(), MemoryStore::new()).await);
    assert_eq!(session.status().state, SessionState::PlanDisabled);
    Mock::given(method("POST"))
        .and(path("/v1/responses"))
        .respond_with(SeqResponder::new(vec![ok(text_stream("never"))]))
        .mount(&fake.server)
        .await;
    let rig = Rig {
        fake,
        session,
        dir,
        gate: ai::PlanGate::new(),
    };
    let mut agent = rig.agent();

    let (result, _) = turn(&mut agent, "hi").await;

    assert_eq!(plan_usage(result).kind(), &PlanUsageKind::PlanDisabled);
    assert!(rig.received("/v1/responses").await.is_empty());

    // And a session nobody signed in to.
    let rig = Rig {
        session: Arc::new(rig.fake.session(
            rig.dir.path().join("elsewhere").as_path(),
            MemoryStore::new(),
        )),
        ..rig
    };
    let mut agent = rig.agent();
    let (result, _) = turn(&mut agent, "hi").await;
    assert_eq!(plan_usage(result).code(), "session_ended");
    assert!(rig.received("/v1/responses").await.is_empty());
}

// ---------------------------------------------------------------------
// The errors page, one by one: typed, one request, no fallback
// ---------------------------------------------------------------------

/// What each answer of the route becomes, and that it is the only request
/// made: nothing is retried, and there is no other provider to fall back to.
#[tokio::test]
async fn every_documented_failure_is_its_own_error_and_stops_the_turn() {
    // (status, body or stream, the code of the error it must become)
    let cases: Vec<(&str, Entry, &str)> = vec![
        (
            "usage limit, before the stream",
            (
                429,
                error_body("subscription_sharing_usage_limit_exceeded", None),
            ),
            "usage_limit",
        ),
        (
            "usage limit, after streaming began",
            ok(failed_stream(
                "subscription_sharing_usage_limit_exceeded",
                "You hit the limit",
            )),
            "usage_limit",
        ),
        (
            "not eligible",
            (
                403,
                error_body("subscription_sharing_user_not_eligible", None),
            ),
            "not_eligible",
        ),
        (
            "usage unavailable, mid-stream",
            ok(failed_stream(
                "subscription_sharing_usage_unavailable",
                "later",
            )),
            "unavailable",
        ),
        (
            "user unavailable",
            (
                503,
                error_body("subscription_sharing_user_unavailable", None),
            ),
            "unavailable",
        ),
        (
            "an admission 503 with no error object",
            (
                503,
                json!({ "detail": "direct routing is off" }).to_string(),
            ),
            "unavailable",
        ),
        (
            "unsupported capability",
            (
                400,
                error_body(
                    "subscription_sharing_unsupported_capability",
                    Some("temperature"),
                ),
            ),
            "unsupported_request",
        ),
        (
            "route not supported",
            (
                403,
                error_body("subscription_sharing_route_not_supported", None),
            ),
            "unsupported_request",
        ),
        (
            "a region policy",
            (403, json!({ "detail": "region not permitted" }).to_string()),
            "refused",
        ),
        (
            "a grant that does not authorise",
            (403, error_body("chatpass_v2_scope_not_authorized", None)),
            "refused",
        ),
        (
            "a 401 that carries a plan code is not renewed for",
            (
                401,
                error_body("subscription_sharing_user_not_eligible", None),
            ),
            "not_eligible",
        ),
        (
            "the Business usage limit",
            (
                429,
                error_body(
                    "subscription_sharing_workplace_individual_usage_limit_exceeded",
                    None,
                ),
            ),
            "usage_limit",
        ),
        (
            "a code of the family nobody listed",
            (403, error_body("subscription_sharing_brand_new_code", None)),
            "refused",
        ),
        (
            "an invalid user",
            (401, error_body("subscription_sharing_invalid_user", None)),
            "session_ended",
        ),
    ];

    for (what, answer, code) in cases {
        let rig = Rig::new().await;
        // A second answer, which a `401` (renewed and sent again) would reach
        // and which a request that was sent elsewhere would too.
        rig.answers(vec![
            answer.clone(),
            answer,
            ok(text_stream("a fallback answer")),
        ])
        .await;
        let mut agent = rig.agent();

        let (result, events) = turn(&mut agent, "hi").await;

        eprintln!("case: {what}");
        let error = plan_usage(result);
        assert_eq!(error.code(), code, "{what}: {error}");
        assert!(
            !events.iter().any(|e| matches!(e, AgentEvent::Done)),
            "{what}: the turn ended as if it had worked"
        );
        // `invalid_user` is a 401, which is renewed once before it is
        // believed, and a transient failure in the stream is tried once more.
        let expected = if what == "an invalid user" || what.starts_with("usage unavailable") {
            2
        } else {
            1
        };
        assert_eq!(
            rig.received("/v1/responses").await.len(),
            expected,
            "{what}: the request was repeated or sent elsewhere"
        );
    }
}

