// ---------------------------------------------------------------------
// The tool ladder (G1), reasoning refusals (G2), retries and ids (G4)
// ---------------------------------------------------------------------

/// A scripted answer with a request ID header.
struct Scripted {
    answers: Vec<(u16, String, Option<&'static str>)>,
    next: Mutex<usize>,
}

impl wiremock::Respond for Scripted {
    fn respond(&self, _: &wiremock::Request) -> ResponseTemplate {
        let mut next = self.next.lock().unwrap();
        let at = *next;
        *next += 1;
        let Some((status, body, id)) = self.answers.get(at) else {
            return ResponseTemplate::new(500).set_body_string("no more answers");
        };
        let mut template = ResponseTemplate::new(*status);
        if let Some(id) = id {
            template = template.insert_header("x-request-id", *id);
        }
        let kind = if body.starts_with("event:") {
            "text/event-stream"
        } else {
            "application/json"
        };
        template
            .insert_header("content-type", kind)
            .set_body_string(body.clone())
    }
}

impl Rig {
    async fn scripted(&self, answers: Vec<(u16, String, Option<&'static str>)>) {
        Mock::given(method("POST"))
            .and(path("/v1/responses"))
            .respond_with(Scripted {
                answers,
                next: Mutex::new(0),
            })
            .mount(&self.fake.server)
            .await;
    }

    fn agent_on(&self, provider: ChatGptProvider, dispatcher: ToolDispatcher) -> Agent {
        self.agent_with(
            LlmConfig::new_chatgpt_with(provider, self.session.clone()),
            dispatcher,
        )
    }
}

fn refused(param: &str) -> (u16, String) {
    (
        400,
        error_body("subscription_sharing_unsupported_capability", Some(param)),
    )
}

/// Which layout a body offers its tools in.
fn layout(body: &Value) -> String {
    if body["input"][0]["type"] == "additional_tools" {
        return "additional_tools".into();
    }
    match body["tools"][0]["type"].as_str() {
        Some("namespace") => "namespace".into(),
        Some("function") => "flat".into(),
        other => format!("none:{other:?}"),
    }
}

fn tool_count(body: &Value) -> usize {
    if body["input"][0]["type"] == "additional_tools" {
        return body["input"][0]["tools"].as_array().unwrap().len();
    }
    match body["tools"][0]["type"].as_str() {
        Some("namespace") => body["tools"][0]["tools"].as_array().unwrap().len(),
        _ => body["tools"].as_array().unwrap().len(),
    }
}

/// The whole ladder, against the real registry: a 400 about `tools` at each
/// rung steps down one, no body is sent twice, the rung that worked is kept
/// for the next turn, and the turn succeeds.
#[tokio::test]
async fn the_tool_ladder_steps_down_on_each_400_and_remembers_the_rung() {
    let rig = Rig::new().await;
    let (status, body) = refused("tools");
    rig.scripted(vec![
        (status, body.clone(), Some("req_1")),
        (status, body.clone(), Some("req_2")),
        (status, body, Some("req_3")),
        (200, text_stream("Done."), None),
        (200, text_stream("And again."), None),
    ])
    .await;
    let provider = rig.provider();
    let mut agent = rig.agent_on(provider, ToolDispatcher::default_dispatcher());

    let (result, events) = turn(&mut agent, "Make track 0 louder by 6 dB.").await;

    assert_eq!(result.expect("the fourth rung works").text, "Done.");
    assert!(events.iter().any(|e| matches!(e, AgentEvent::Done)));
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 4);
    let layouts: Vec<String> = bodies.iter().map(layout).collect();
    assert_eq!(
        layouts,
        ["namespace", "namespace", "additional_tools", "flat"]
    );
    let count = ToolDispatcher::default_dispatcher().tool_names().len();
    assert_eq!(tool_count(&bodies[0]), count, "the whole list first");
    assert!(
        tool_count(&bodies[1]) < count / 2,
        "then the slim list, still in the namespace"
    );
    assert_eq!(
        tool_count(&bodies[2]),
        count,
        "then all of them in the item"
    );
    assert_eq!(tool_count(&bodies[3]), count, "then all of them, flat");
    for (i, a) in bodies.iter().enumerate() {
        for b in &bodies[i + 1..] {
            assert_ne!(a, b, "one body was sent twice");
        }
    }
    // The slim request names the tools it left out, as on Ollama.
    assert!(bodies[1]["instructions"]
        .as_str()
        .unwrap()
        .contains("More tools you can call by exact name"));
    assert!(!bodies[2]["instructions"]
        .as_str()
        .unwrap()
        .contains("More tools you can call by exact name"));

    // The next turn starts where the last ended.
    let (again, _) = turn(&mut agent, "and again").await;
    again.expect("the next turn");
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 5, "no refusal learned twice");
    assert_eq!(layout(&bodies[4]), "flat");
}

