/// A step down changes the tools the earlier steps' reasoning was produced
/// under, so what the turn kept of it is dropped, not replayed.
#[tokio::test]
async fn a_step_down_mid_turn_drops_the_reasoning_made_under_the_old_layout() {
    let rig = Rig::new().await;
    let (status, body) = refused("tools");
    rig.scripted(vec![
        (200, tool_stream(Some("ENC-OLD"), "call_1"), None),
        (status, body, None),
        (200, text_stream("Done."), None),
    ])
    .await;
    // The real registry has an `echo` tool, which is what the stream calls.
    let mut agent = rig.agent_on(rig.provider(), ToolDispatcher::default_dispatcher());

    let (result, _) = turn(&mut agent, "check track 1").await;

    result.expect("the turn succeeds");
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 3);
    assert!(
        bodies[1].to_string().contains("ENC-OLD"),
        "within the layout it came from"
    );
    assert!(
        !bodies[2].to_string().contains("ENC-OLD"),
        "replayed under another layout: {}",
        bodies[2]
    );
    assert_ne!(
        tool_count(&bodies[1]),
        tool_count(&bodies[2]),
        "another tool list"
    );
}

/// G2: a route that does not take `include` is carried on without it.
#[tokio::test]
async fn a_400_about_include_drops_it_and_carries_on() {
    let rig = Rig::new().await;
    let (status, body) = refused("include");
    rig.scripted(vec![
        (status, body, None),
        (200, tool_stream(Some("ENC-1"), "call_1"), None),
        (200, text_stream("Done."), None),
    ])
    .await;
    let mut agent = rig.agent();

    let (result, _) = turn(&mut agent, "check track 1").await;

    result.expect("the turn succeeds");
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 3);
    assert!(bodies[0].get("include").is_some());
    for body in &bodies[1..] {
        assert!(body.get("include").is_none(), "{body}");
        assert!(
            !body.to_string().contains("ENC-1"),
            "reasoning is off: {body}"
        );
    }
}

/// G4 (e): a transient failure in the stream, before anything of the step was
/// shown, is tried once more with the same request; the others are not.
#[tokio::test]
async fn a_transient_failure_in_the_stream_is_tried_once_more() {
    let rig = Rig::new().await;
    rig.answers(vec![
        ok(failed_stream("server_error", "oops")),
        ok(text_stream("Second time lucky.")),
    ])
    .await;
    let mut agent = rig.agent();

    let (result, events) = turn(&mut agent, "hi").await;

    assert_eq!(
        result.expect("the retry succeeds").text,
        "Second time lucky."
    );
    let bodies = rig.bodies().await;
    assert_eq!(bodies.len(), 2);
    assert_eq!(bodies[0], bodies[1], "the same request, once");
    assert_eq!(
        events
            .iter()
            .filter(|e| matches!(e, AgentEvent::Done))
            .count(),
        1
    );

    // A second failure is the answer.
    let rig = Rig::new().await;
    rig.answers(vec![
        ok(failed_stream("rate_limit_exceeded", "slow down")),
        ok(failed_stream("rate_limit_exceeded", "slow down")),
        ok(text_stream("never")),
    ])
    .await;
    let mut agent = rig.agent();
    let (result, _) = turn(&mut agent, "hi").await;
    assert_eq!(plan_usage(result).code(), "unavailable");
    assert_eq!(rig.bodies().await.len(), 2, "once, not forever");
}

